replacements.new:
.why-reasons .book-quote{background:var(--hp-midnight);color:var(--hp-quote)}
/* Separate each before/after label from its quote, preserving the existing type. */
.why-reasons .book-quote{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:10px 12px;align-items:baseline}
.why-reasons .book-quote .quote-label{font-size:.75em;font-style:normal;line-height:inherit;letter-spacing:.06em;text-transform:uppercase}
.why-reasons .book-quote .quote-from{color:var(--hp-coral)}
.why-reasons .book-quote .quote-to{color:var(--hp-lime)}
.why-reasons .book-quote .quote-text{font-size:inherit;line-height:inherit}
